mapper.select:
SELECT d.id, d.restaurant_id, d.category_id, r.name AS restaurant_name, dc.category_name, d.dish_name,
CASE WHEN d.cover_img_url IS NOT NULL AND d.cover_img_url != '' THEN CONCAT('/uploads/', d.cover_img_url) ELSE d.cover_img_url END AS cover_img_url, d.dish_status, d.price, d.unit, d.summary, d.create_time, d.update_time FROM dish d LEFT JOIN restaurant r ON d.restaurant_id = r.id LEFT JOIN dish_category dc ON d.category_id = dc.id WHERE d.is_deleted = 0 AND d.restaurant_id = #{restaurantId}
AND d.dish_name LIKE CONCAT('%', #{dishName}, '%')
AND dc.category_name LIKE CONCAT('%', #{categoryName}, '%')
AND d.dish_status = #{status}
ORDER BY d.sort_num ASC, d.create_time DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM dish d LEFT JOIN restaurant r ON d.restaurant_id = r.id LEFT JOIN dish_category dc ON d.category_id = dc.id WHERE d.is_deleted = 0 AND d.restaurant_id = #{restaurantId}
AND d.dish_name LIKE CONCAT('%', #{dishName}, '%')
AND dc.category_name LIKE CONCAT('%', #{categoryName}, '%')
AND d.dish_status = #{status}
